/**
 * @description Tests for the What's implemented & usage and Who uses Integration Hub scan: admin scan, reader refused,
 * plugged-in class of the test events, transaction counts, publish key parser and test class detection.
 */
@IsTest
private class IntegrationHubUsageTest {

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    private static IntegrationHubUsage.CodeRow codeRow(IntegrationHubUsage.Scan s, String name) {
        for (IntegrationHubUsage.CodeRow row : s.code) {
            if (row.name == name) {
                return row;
            }
        }
        return null;
    }

    @IsTest
    static void adminScanReturnsTheFrameworkClasses() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubUsage.Scan s = IntegrationHubUsage.scan();
            Assert.isTrue(s.admin, 'the admin gets the live numbers');
            IntegrationHubUsage.CodeRow hub = codeRow(s, 'IntegrationHub');
            Assert.isNotNull(hub, 'the framework class is read');
            Assert.isTrue(hub.chars > 0, 'its characters are read');
            Assert.isFalse(hub.isTest, 'it is not a test');
            Assert.isTrue(codeRow(s, 'IntegrationHubUsageTest').isTest, 'a test class is recognised');
            Assert.isFalse(codeRow(s, 'IntegrationHubUsage').isTest, 'the scan class itself is not a test');
            IntegrationHubUsage.CodeRow trg = codeRow(s, 'IH_TransactionTrigger');
            Assert.isNotNull(trg, 'the trigger is read');
            Assert.areEqual(IntegrationHubUsage.KIND_TRIGGER, trg.kind, 'as a trigger');
            Assert.areEqual(IntegrationHubUsage.APEX_LIMIT, s.apexLimit, 'the Apex limit is returned');
            Assert.areEqual(IntegrationHubUsage.OBJECTS.size(), s.objects.size(), 'every object is described');
            Assert.isTrue(s.objects[1].customFields > 0, 'the custom fields are counted');
            Assert.areEqual(IntegrationHubUsage.JOB_CLASSES.size(), s.jobClasses.size(), 'the job classes are found');
            Assert.areEqual(3, s.events.size(), 'the test events are returned');
        }
    }

    @IsTest
    static void transactionsOfTheLastDayAreCounted() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubUsage.Scan s = IntegrationHubUsage.scan();
            Assert.areEqual(1, s.transactions.size(), 'one count row');
            Assert.areEqual(String.valueOf(IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Id),
                s.transactions[0].key, 'per event');
            Assert.areEqual('Failed', s.transactions[0].status, 'per status');
            Assert.areEqual(1, s.transactions[0].count, 'the transaction is counted');
            Assert.isNotNull(s.transactions[0].lastAt, 'the last time is set');
            Assert.isNotNull(t.Id, 'the transaction was saved');
        }
    }

    @IsTest
    static void readerGetsNoLiveData() {
        System.runAs(IntegrationHubTestData.reader()) {
            IntegrationHubUsage.Scan s = IntegrationHubUsage.scan();
            Assert.isFalse(s.admin, 'a reader is not an admin');
            Assert.isNotNull(s.message, 'the reader gets a note');
            Assert.isTrue(s.code.isEmpty(), 'no code for a reader');
            Assert.isTrue(s.events.isEmpty(), 'no events for a reader');
            Assert.isTrue(s.jobs.isEmpty(), 'no jobs for a reader');
        }
    }

    @IsTest
    static void pluggedInClassOfTheTestEventsIsFound() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubUsage.Scan s = IntegrationHubUsage.scan();
            Set<String> names = IntegrationHubUsage.pluginNames(s);
            Assert.isTrue(names.contains('IntegrationHubTestData.StubResponse'), 'the response handler of the test events');
            Assert.isTrue(names.contains('IntegrationHubTestData.StubInbound'), 'the inbound handler of the test events');
            Assert.isFalse(names.contains(null), 'blank class fields are left out');
            Assert.isTrue(codeRow(s, 'IntegrationHubTestData').chars > 0, 'the class holding them is read');
            Assert.isTrue(codeRow(s, 'IntegrationHubPayloadTest').mentions.contains('IntegrationHubTestData.StubResponse'),
                'a test class that mentions the plugged-in class is found');
            Assert.isFalse(codeRow(s, 'IntegrationHubTestData').mentions.contains('IntegrationHubTestData.StubResponse'),
                'the class itself does not count as its test');
        }
    }

    @IsTest
    static void eventKeysAreReadFromPublishLines() {
        System.runAs(IntegrationHubTestData.admin()) {
            String code = 'List<Id> ids = IntegrationHub.publish(\'CASE_VOUCHER_REQ\', cases);\n'
                + 'integrationhub.Publish( \'ORDER_SYNC\' , new List<Id>(idSet));\n'
                + 'IntegrationHub.publish(\'CASE_VOUCHER_REQ\', more);\n'
                + 'IntegrationHub.publish(eventKey, records);';
            Assert.areEqual(new List<String>{ 'CASE_VOUCHER_REQ', 'ORDER_SYNC' }, IntegrationHubUsage.eventKeys(code),
                'each literal key once, in order; a variable is skipped');
            Assert.isTrue(IntegrationHubUsage.eventKeys(null).isEmpty(), 'no code, no keys');
            Assert.isTrue(IntegrationHubUsage.eventKeys('IntegrationHub.publish').isEmpty(), 'no call, no key');
        }
    }

    @IsTest
    static void testClassesAreRecognised() {
        System.runAs(IntegrationHubTestData.admin()) {
            Assert.isTrue(IntegrationHubUsage.isTestClass('MyTests', '@isTest private class MyTests {}'), 'an @IsTest body');
            Assert.isFalse(IntegrationHubUsage.isTestClass('MyService', 'public class MyService {}'), 'a normal class');
            Assert.isTrue(IntegrationHubUsage.isTestClass('PkgServiceTest', '(hidden)'), 'a hidden body ending with Test');
            Assert.isFalse(IntegrationHubUsage.isTestClass('PkgService', '(hidden)'), 'a hidden body not ending with Test');
        }
    }
}
